import { uv, mix, smoothstep, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
    const {
        Group,
        Mesh,
        PlaneGeometry,
        MeshBasicNodeMaterial,
        DirectionalLight,
        AmbientLight,
        Color,
        DoubleSide,
    } = ctx.THREE;

    const root = new Group();

    // ---------- Backdrop Gradient ----------
    const gradNode = (() => {
        const uvNode = uv();
        // Fixed gradient stops as defined in the spec
        let col = color(new Color('#0b0b10'));
        col = mix(col, color(new Color('#101017')), smoothstep(0.0, 0.55, uvNode.y));
        col = mix(col, color(new Color('#16161d')), smoothstep(0.55, 1.0, uvNode.y));
        return col;
    })();

    const backdropMat = new MeshBasicNodeMaterial({ color: gradNode, side: DoubleSide });
    const backdropGeo = new PlaneGeometry(7, 6);
    const backdrop = new Mesh(backdropGeo, backdropMat);
    backdrop.position.set(0, 0, -2.5);
    root.add(backdrop);

    // ---------- Contact Shadow ----------
    const shadowMat = new MeshBasicNodeMaterial({
        color: 0x000000,
        transparent: true,
        opacity: 0.55,
        side: DoubleSide,
    });
    const shadowGeo = new PlaneGeometry(3.2, 3.2);
    const shadow = new Mesh(shadowGeo, shadowMat);
    shadow.rotation.x = -Math.PI / 2;
    // plinth top face at y = -1.1, shadow just below
    shadow.position.set(0, -1.101, 0);
    root.add(shadow);

    // ---------- Lights ----------
    const ambient = new AmbientLight(0xffffff, 0.6);
    root.add(ambient);

    const keyLight = new DirectionalLight(0xffffff, 1.2);
    keyLight.position.set(2, 2, 2);
    root.add(keyLight);

    const rimLight = new DirectionalLight(0xff2a38, 0.8);
    rimLight.position.set(-2, 0, 0);
    root.add(rimLight);

    // ---------- Load Watch GLB ----------
    if (config.meshUrl) {
        ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
            root.add(gltf.scene);
        });
    }

    // ---------- Text Content ----------
    const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
    const paperHex = (config.visualSpec?.colors?.paper ?? config.colors?.paper) ?? '#e8ecf2';
    const textGroup = new Group();
    root.add(textGroup);

    items.forEach((item) => {
        const opts = {
            fontSize: item.typography?.fontSize,
            color: paperHex,
            align: 'center',
        };
        const txt = ctx.fontAtlas.createText(item.text, opts);
        let y = 0;
        if (item.role === 'headline') {
            y = -1.5;
        } else if (item.role === 'caption') {
            y = -2.0;
        } else {
            // body or any other role
            y = -1.8;
        }
        txt.position.set(0, y, 0.01);
        textGroup.add(txt);
    });

    // ---------- Cinematic Primitives ----------
    const primitiveInstances = [];
    (config.cinematicPrimitives ?? []).forEach((p) => {
        const fn = ctx.primitives[p.name];
        if (typeof fn === 'function') {
            const inst = fn(root, p.params);
            primitiveInstances.push(inst);
        }
    });

    // ---------- UserData Handlers ----------
    root.userData.handlers = {};

    // ---------- Cleanup ----------
    root.userData.cleanup = () => {
        primitiveInstances.forEach((inst) => {
            if (inst && typeof inst.cleanup === 'function') inst.cleanup();
        });
        backdropGeo.dispose();
        backdropMat.dispose();
        shadowGeo.dispose();
        shadowMat.dispose();
        // Clear any global GSAP timelines that might have been created elsewhere
        if (gsap && typeof gsap.globalTimeline?.clear === 'function') {
            gsap.globalTimeline.clear();
        }
    };

    return root;
}
